-- Register the five original banners for each language without resetting later edits.
-- Products, prices, stock, customer records and Cloudinary assets are untouched.
begin;
do $positions$ begin
if not exists(select 1 from public.homepage_slides where legacy_locale like 'builtin:%') then
  update public.homepage_slides set position=least(100000,position+5) where legacy_locale is null or legacy_locale not like 'builtin:%';
end if;
end $positions$;
on conflict (legacy_locale) do nothing;
-- Older deployed carousels still contain the five originals in source. Keep
-- their ordinary public table read limited to added banners to avoid duplicates.
-- The new public reader returns only published, non-deleted banners of one locale.
create or replace function public.homepage_published_slides(requested_locale text)
returns setof public.homepage_slides language sql stable security definer set search_path='' as $reader$
  select * from public.homepage_slides where locale=requested_locale and enabled and not archived order by position,id;
$reader$;
revoke all on function public.homepage_published_slides(text) from public;
grant execute on function public.homepage_published_slides(text) to anon,authenticated;
drop policy if exists "public reads published homepage slides" on public.homepage_slides;
create policy "public reads published homepage slides" on public.homepage_slides for select to anon,authenticated
  using(enabled and not archived and (legacy_locale is null or legacy_locale not like 'builtin:%'));
notify pgrst, 'reload schema';
commit;
